from collections import defaultdict

def week_counts(days: list[int]) -> dict[int, int]:
    totals = defaultdict(int)
    for day in days:
        week = week_of(day)
        totals[week] += 1
    return dict(sorted(totals.items(), key=lambda kv: kv[1], reverse=True))
