def split_labels(total_cents: int, people: int) -> list[str]:
    """Split a bill exactly, with each share as a price label."""
    base, extra = divmod(total_cents, people)
    labels = []
    for i in range(people):
        if i < extra:
            labels.append(f"{base + 1} Kes")
        else:
            labels.append(f"{base} Kes")
    return labels
```

